import importlib.util,zipfile,xml.etree.ElementTree as ET
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
spec=importlib.util.spec_from_file_location('ux',Path(__file__).with_name('browser-editor-ux.py'));ux=importlib.util.module_from_spec(spec);spec.loader.exec_module(ux)
f=ux.fixture;BASE='http://127.0.0.1:4173/';XDR='{http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing}';A='{http://schemas.openxmlformats.org/drawingml/2006/main}'
NATIVE='''<xdr:oneCellAnchor><xdr:from><xdr:col>9</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>4</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from><xdr:ext cx="1524000" cy="857250"/><xdr:sp><xdr:nvSpPr><xdr:cNvPr id="10" name="Original Template Shape"/><xdr:cNvSpPr/></xdr:nvSpPr><xdr:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="1524000" cy="857250"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:gradFill><a:gsLst><a:gs pos="0"><a:srgbClr val="FF0000"/></a:gs><a:gs pos="100000"><a:srgbClr val="0000FF"/></a:gs></a:gsLst><a:lin ang="0" scaled="1"/></a:gradFill><a:ln w="19050"><a:solidFill><a:schemeClr val="accent1"/></a:solidFill><a:prstDash val="dash"/><a:headEnd type="triangle"/></a:ln></xdr:spPr><xdr:txBody><a:bodyPr anchor="t"/><a:lstStyle/><a:p><a:pPr algn="l"/><a:r><a:rPr b="1" i="1" sz="1800"/><a:t>First line</a:t></a:r><a:br/><a:r><a:rPr sz="1400"/><a:t>Second line</a:t></a:r></a:p></xdr:txBody></xdr:sp><xdr:clientData/></xdr:oneCellAnchor>'''
def download(page):
 with page.expect_download() as dl:page.get_by_role('button',name='Unduh Excel',exact=True).click()
 with zipfile.ZipFile(dl.value.path()) as z:return ET.fromstring(z.read('xl/drawings/drawing1.xml'))
def run():
 drawing=f.parts['xl/drawings/drawing1.xml'].replace('</xdr:wsDr>',NATIVE+'</xdr:wsDr>');baseline=ET.fromstring(drawing).find('.//'+XDR+'sp')
 with sync_playwright() as p:
  browser=p.chromium.launch(channel='chromium');page=browser.new_page(viewport={'width':1440,'height':1000},accept_downloads=True);page.goto(BASE);f.login(page,'admin');f.upload(page,f.pack({'xl/drawings/drawing1.xml':drawing}));page.goto(BASE+'#create');page.locator('#doc-title').fill('Native shape preservation');f.choose(page,'Jenis dokumen','Instruksi Kerja');f.choose(page,'Kategori dokumen','LEGACY');f.save_and_open(page);shape=page.locator('.workbook-shape');expect(shape).to_have_count(1);assert shape.locator('.workbook-shape-label').text_content()=='First line\nSecond line'
  before=shape.bounding_box();page.mouse.move(before['x']+12,before['y']+12);page.mouse.down();page.mouse.move(before['x']+65,before['y']+35,steps=8);page.mouse.up();assert shape.bounding_box()['x']>before['x']+40
  sp=download(page).find('.//'+XDR+'sp');assert ET.tostring(sp.find(XDR+'txBody'))==ET.tostring(baseline.find(XDR+'txBody'));assert ET.tostring(sp.find(XDR+'spPr/'+A+'gradFill'))==ET.tostring(baseline.find(XDR+'spPr/'+A+'gradFill'));assert ET.tostring(sp.find(XDR+'spPr/'+A+'ln'))==ET.tostring(baseline.find(XDR+'spPr/'+A+'ln'))
  page.keyboard.press('Control+s');expect(page.locator('#workbook-save-status')).to_have_text('Semua perubahan tersimpan');page.reload();shape=page.locator('.workbook-shape');shape.wait_for();assert shape.bounding_box()['x']>before['x']+40;sp=download(page).find('.//'+XDR+'sp');assert ET.tostring(sp.find(XDR+'txBody'))==ET.tostring(baseline.find(XDR+'txBody'))
  shape.click();page.get_by_role('button',name='Edit Bentuk',exact=True).click();page.locator('#shape-text').fill('Edited explicitly');page.get_by_role('button',name='Terapkan Bentuk',exact=True).click();sp=download(page).find('.//'+XDR+'sp');assert 'Edited explicitly' in ''.join(sp.itertext());assert sp.find(XDR+'spPr/'+A+'gradFill') is None
  print('PASS native template shape drag/save/reload preserves rich text, line breaks, gradient, theme/dashed/arrow line; explicit Format Shape updates selected properties',flush=True);page.once('dialog',lambda d:d.accept());browser.close()
if __name__=='__main__':run()
